<?php require_once 'config.php'; if (!empty($_SESSION['user'])) { header('Location: index.php'); exit; } $error=''; if ($_SERVER['REQUEST_METHOD']==='POST') { $email=trim($_POST['email']??''); $password=$_POST['password']??''; $st=$pdo->prepare('SELECT id,name,email,password,role FROM users WHERE email=? LIMIT 1'); $st->execute([$email]); $u=$st->fetch(); if ($u && password_verify($password,$u['password'])) { unset($u['password']); $_SESSION['user']=$u; header('Location: '.($u['role']==='admin'?'admin.php':'dashboard.php')); exit; } $error='Email or password is incorrect.'; } $page_title='Sign in'; include 'includes/header.php'; ?>
<section class="auth-page"><div class="auth-visual"><div class="visual-badge">CAMPUS OPERATIONS</div><h1>Make campus better, <em>one issue at a time.</em></h1><p>Report problems, follow progress, and help your campus team keep things running smoothly.</p><div class="visual-flow"><span>Report</span><i>→</i><span>Resolve</span><i>→</i><span>Done</span></div></div><div class="auth-card"><div class="eyebrow">WELCOME BACK</div><h2>Sign in to CampusCare</h2><p class="muted">Use your campus account to continue.</p><?php if($error): ?><div class="alert error">⚠ <?=e($error)?></div><?php endif; ?><form method="post" class="form-stack"><label>Email<input type="email" name="email" required autocomplete="email" placeholder="you@campus.edu"></label><label>Password<input type="password" name="password" required autocomplete="current-password" placeholder="••••••••"></label><button class="btn btn-primary btn-wide" type="submit">Sign in <span>→</span></button></form><div class="demo-box"><b>Demo access</b><span>Student: student@campus.local / password123</span><span>Admin: admin@campus.local / admin123</span></div></div></section><?php include 'includes/footer.php'; ?>
